/** Périmètre de calcul des performances : entités effectivement vérifiées (exclut NON_AUDITE). */
export const COHORTE_VERIFIEE: ValidationEntry[] =
  COHORTE_VALIDATION.filter(e => e.audit !== 'NON_AUDITE' && e.iro != null);

/** Événement d'intérêt — défaillance avérée UNIQUEMENT (cf. SCI-A). */
export function estDefaillance(e: ValidationEntry): boolean {
  return e.status === 'failed';
}

